// 2. Setup the Box we want to move
box.visible = true;
box.x = 0;
box.y = 0;
box.color = "#4ECDC4";
box.eyes = true;
// 3. The magic connection!
joystick.onMove = function(x, y) {
    // Because minX is -15, going left makes x negative, which subtracts from box.x!
    box.x += x;
    box.y += y;
    
    // Let's watch the numbers in the console
    console.log("Joystick -> X:", x, " Y:", y);
};

