// --- Ťahák (Nápoveda) pre programovanie ---
// Tento kód sa nespustí automaticky celý, slúži ako príklad!
// Ak chceš niečo vyskúšať, skopíruj si to do svojho súboru a klikni RUN CODE!

// 1. ZÁKLADY (Mením farbu, veľkosť, pozíciu)
box.color = 'blue';       // Krabica bude modrá
box.width = 200;          // Krabica bude široká 200
box.height = 300;         // Krabica bude vysoká 300
box.x = 100;              // Posunie krabicu doprava o 100
box.y = -50;              // Posunie krabicu nahor o 50
box.angle = 45;           // Otočí krabicu (šikmo)
box.borders = 10;         // Pridá krabici rámik
box.visible = false;      // Schová krabicu (nebude ju vidieť)

// 2. STATUS A STENA (Okolie)
wall.color = 'yellow';    // Stena v pozadí bude žltá
wall.borders = 20;        // Stena bude mať hrubý rám

status.text("Ahoj!");     // Napíše "Ahoj!" do nápovedy (statusu)
status.color = "pink";    // Pozadie statusu bude ružové
status.borders = 4;       // Status bude mať rámik
status.x = 0;             // Posunie status (0 = stred)

// 3. OČI, ÚSTA A KONČATINY (Booleans - Pravda / Lož)
box.eyes = true;          // Krabica bude mať oči
box.smile = true;         // Krabica sa bude usmievať
box.nose = false;         // Krabica nebude mať nos
box.hands = true;         // Krabica bude mať ruky
box.legs = true;          // Krabica bude mať nohy
box.hair = true;          // Krabica bude mať vlasy
box.glasses = true;       // Krabica bude mať okuliare

// 4. KONZOLA A PREMENNÉ
console.log("Ahoj svet!");      // Vypíše "Ahoj svet!" do konzoly
let meno = "Radko";             // Vytvorí premennú meno
console.log("Volám sa " + meno); // Spojí text a premennú a vypíše

// 5. PODMIENKY (Ak sa niečo deje)
if (isSunny) {
  // Ak je slnečno (isSunny)
  box.color = 'yellow';
} else if (isRaining) {
  // Ak prší (isRaining)
  box.color = 'blue';
} else if (isNight) {
  // Ak je noc (isNight)
  box.color = 'black';
}

// 6. CYKLY (Opakovanie)
// FOR cyklus - zopakuje príkaz 5-krát
for (let i = 0; i < 5; i = i + 1) {
  box.x = box.x + 10; // Posunie krabicu o 10 doprava päťkrát
}

// 7. ČASOVAČE A ANIMÁCIE
// setTimeout (Urobí to len raz, po 1 sekunde = 1000ms)
setTimeout(() => {
  box.color = 'red';
}, 1000);

// setInterval (Bude to robiť dookola každých 100 milisekúnd)
setInterval(() => {
  box.angle = box.angle + 10; // Krabica sa bude točiť
}, 100);

// 8. CREEPER (Kamoš)
creeper.x = 200;           // Posunie Creepera
creeper.mouth = false;     // Schová mu ústa
creeper.visible = true;    // Ukáže Creepera

